(800290, 88339, 22734, '<td valign="top">This shot is certainly a winner Would have been stronger with cup displaying brand.</td>', 'This shot is certainly a winner Would have been stronger with cup displaying brand.', '2004-07-07 14:55:25.000000', NULL, 1),
