(800299, 88255, 22734, '<td valign="top">Very impressive even as ligthing fails a bit at bottom.</td>', 'Very impressive even as ligthing fails a bit at bottom.', '2004-07-07 14:58:21.000000', NULL, 1),
(800300, 88934, 21430, '<td valign="top">What''s up with the eyes on this cat? It looks, I dunno, almost cross-eyed.<br/> <br/>This shot greatly meets the challenge and is really well put together. With that background the cat and the product really sticks out. The only thing that isn''t purr-fect is the white light/flash showing up on the top Whiskas can.</td>', 'What''s up with the eyes on this cat? It looks, I dunno, almost cross-eyed. This shot greatly meets the challenge and is really well put together. With that background the cat and the product really sticks out. The only thing that isn''t purr-fect is the white light/flash showing up on the top Whiskas can.', '2004-07-07 14:58:41.000000', NULL, 1),
(800302, 89054, 22734, '<td valign="top">Very cool effect. Would have prefered  bottle perpenducular, but otherwise a fantastic shot.</td>', 'Very cool effect. Would have prefered  bottle perpenducular, but otherwise a fantastic shot.', '2004-07-07 15:00:28.000000', NULL, 1),
(800304, 89212, 21430, '<td valign="top">Wow, very nice shot. <br/> <br/>I would like to see how this was done, I can''t even begin to guess. Wait a minute, it looks like you might have suction-cupped or otherwise glued this to a windoe. Ingenious.<br/> <br/>I like the focus, I like the composition.</td>', 'Wow, very nice shot.  I would like to see how this was done, I can''t even begin to guess. Wait a minute, it looks like you might have suction-cupped or otherwise glued this to a windoe. Ingenious. I like the focus, I like the composition.', '2004-07-07 15:01:29.000000', NULL, 1),
(800306, 88242, 22734, '<td valign="top">Very strong with red behind. Great visual impact.</td>', 'Very strong with red behind. Great visual impact.', '2004-07-07 15:01:39.000000', NULL, 1),
(800308, 88817, 18820, '<td valign="top">Like the forums and comments aren''t demeaning enough... now your camera can tell you that you have no talent.  Ha  Very funny!</td>', 'Like the forums and comments aren''t demeaning enough... now your camera can tell you that you have no talent.  Ha  Very funny!', '2004-07-07 15:03:00.000000', NULL, 1),
