(801313, 88879, 17279, '<td valign="top">I like the idea.  I would have cropped tighter on the single class in portrait orientation.  If possible, try to get the same texture of dark with light streaks going from the top of the glass to the bottom.</td>', 'I like the idea.  I would have cropped tighter on the single class in portrait orientation.  If possible, try to get the same texture of dark with light streaks going from the top of the glass to the bottom.', '2004-07-07 23:14:31.000000', NULL, 1),
(801326, 89179, 17279, '<td valign="top">Great shot... only three things...lack of sharp focus on the near chain, cutting off on the left and the sticker on top.  Could have been a 10, but I still give this a 9!</td>', 'Great shot... only three things...lack of sharp focus on the near chain, cutting off on the left and the sticker on top.  Could have been a 10, but I still give this a 9!', '2004-07-07 23:17:01.000000', NULL, 1),
