(801549, 89229, 18780, '<td valign="top">Good product shot...but the nude doesn''t make me feel thirsty.</td>', 'Good product shot...but the nude doesn''t make me feel thirsty.', '2004-07-08 00:35:13.000000', NULL, 1),
(801553, 89335, 19841, '<td valign="top">Would you believe I would rather see this in color?  I think  subtle reflected colors in the stones would show off the purity of  platinum better.  Interesting composition, I can imagine  ad text  in the empty space.</td>', 'Would you believe I would rather see this in color?  I think  subtle reflected colors in the stones would show off the purity of  platinum better.  Interesting composition, I can imagine  ad text  in the empty space.', '2004-07-08 00:36:27.000000', NULL, 1),
(801559, 88873, 18780, '<td valign="top">Excellent shot of a flower...too big a leap for me to butter.</td>', 'Excellent shot of a flower...too big a leap for me to butter.', '2004-07-08 00:39:42.000000', NULL, 1),
(801585, 86995, 18780, '<td valign="top">Love your humor....</td>', 'Love your humor....', '2004-07-08 00:53:57.000000', NULL, 1),
(801592, 88356, 23256, '<td valign="top">hahaha. amazing</td>', 'hahaha. amazing', '2004-07-08 00:58:54.000000', NULL, 1),
(801594, 88294, 16106, '<td valign="top">the white lines on the pavment really hurt this shot, If you couldn''t get rid of them you might put them at the front wheel so it might look ( sorta) like a starting line. Other than that a nice composition, but it is tough to shoot a hot car as well as we see them in the advertisments.</td>', 'the white lines on the pavment really hurt this shot, If you couldn''t get rid of them you might put them at the front wheel so it might look ( sorta) like a starting line. Other than that a nice composition, but it is tough to shoot a hot car as well as we see them in the advertisments.', '2004-07-08 01:01:20.000000', NULL, 1),
