(802983, 88127, 22913, '<td valign="top">Nice, but the colour cast is a tiny bit much. Great idea though</td>', 'Nice, but the colour cast is a tiny bit much. Great idea though', '2004-07-08 20:54:17.000000', NULL, 1),
(802989, 89213, 22913, '<td valign="top">Very nice effect, lighting is great, Makes me want to by them</td>', 'Very nice effect, lighting is great, Makes me want to by them', '2004-07-08 20:56:36.000000', NULL, 1),
(802990, 88894, 22913, '<td valign="top">Brilliant, makes me thirsty just looking at it. Well done</td>', 'Brilliant, makes me thirsty just looking at it. Well done', '2004-07-08 20:57:20.000000', NULL, 1),
(802994, 89166, 22913, '<td valign="top">I got a laugh out of this because the Caption suits the photo so well.</td>', 'I got a laugh out of this because the Caption suits the photo so well.', '2004-07-08 20:59:32.000000', NULL, 1),
(802997, 88837, 22913, '<td valign="top">Sold! you got me here, Nice photo and has meaning.</td>', 'Sold! you got me here, Nice photo and has meaning.', '2004-07-08 21:01:35.000000', NULL, 1),
(802998, 88339, 22913, '<td valign="top">Dog shots are always great. Looks like me in the morning before my coffee. Well done.</td>', 'Dog shots are always great. Looks like me in the morning before my coffee. Well done.', '2004-07-08 21:02:41.000000', NULL, 1),
(803000, 88657, 22913, '<td valign="top">Nice effect the glasses grabbed my attention right from the start. Well done</td>', 'Nice effect the glasses grabbed my attention right from the start. Well done', '2004-07-08 21:03:53.000000', NULL, 1),
(803001, 88816, 19751, '<td valign="top">too much white, but nice idea</td>', 'too much white, but nice idea', '2004-07-08 21:05:30.000000', NULL, 1),
(803002, 89013, 19751, '<td valign="top">I think this type of picture would be best against a plain background</td>', 'I think this type of picture would be best against a plain background', '2004-07-08 21:06:42.000000', NULL, 1),
