INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(803005, 89200, 19751, '<td valign="top">Good ad. The crop looks a little tight though.</td>', 'Good ad. The crop looks a little tight though.', '2004-07-08 21:07:52.000000', NULL, 1),
(803009, 89178, 19751, '<td valign="top">this doesnt really seem like an ad... just another flower picture...</td>', 'this doesnt really seem like an ad... just another flower picture...', '2004-07-08 21:09:10.000000', NULL, 1),
