(804751, 89274, 19841, '<td valign="top">Great idea.  The only thing this needs is crisper lighting.  It looks like an overcast day, and Cuervo should be tropical sunny.</td>', 'Great idea.  The only thing this needs is crisper lighting.  It looks like an overcast day, and Cuervo should be tropical sunny.', '2004-07-10 10:17:52.000000', NULL, 1),
(804756, 89169, 19841, '<td valign="top">The tropical fish is exotic, but putting it in the wineglass is a little icky.  Otherwise a great shot.</td>', 'The tropical fish is exotic, but putting it in the wineglass is a little icky.  Otherwise a great shot.', '2004-07-10 10:46:58.000000', NULL, 1),
(804757, 88633, 19841, '<td valign="top">They have all gone a little green.</td>', 'They have all gone a little green.', '2004-07-10 10:50:09.000000', NULL, 1),
