(804762, 88242, 23098, '<td valign="top">Good photo with super colors -- the lines on the background and on the can work so well together.</td>', 'Good photo with super colors -- the lines on the background and on the can work so well together.', '2004-07-10 10:57:18.000000', NULL, 1),
(804763, 88413, 19841, '<td valign="top">A little washed out, but a great composition!</td>', 'A little washed out, but a great composition!', '2004-07-10 10:58:07.000000', NULL, 1),
(804765, 89284, 19841, '<td valign="top">Whatever that is in the upper left corner is an unfortunate distraction, but the dog''s expression is great!</td>', 'Whatever that is in the upper left corner is an unfortunate distraction, but the dog''s expression is great!', '2004-07-10 10:59:20.000000', NULL, 1),
(804767, 89308, 23098, '<td valign="top">good colors, dof and well composed -- nice work.</td>', 'good colors, dof and well composed -- nice work.', '2004-07-10 11:01:31.000000', NULL, 1),
(804769, 88184, 19841, '<td valign="top">Walking through a jungle!  I love it!</td>', 'Walking through a jungle!  I love it!', '2004-07-10 11:05:44.000000', NULL, 1),
(804771, 89102, 23098, '<td valign="top">Very nicely done--lighting, detail are great.</td>', 'Very nicely done--lighting, detail are great.', '2004-07-10 11:06:38.000000', NULL, 1),
(804772, 88934, 23098, '<td valign="top">Good one.</td>', 'Good one.', '2004-07-10 11:09:40.000000', NULL, 1),
(804776, 88932, 21909, '<td valign="top">Great use of light and color</td>', 'Great use of light and color', '2004-07-10 11:29:30.000000', NULL, 1),
(804780, 89312, 7485, '<td valign="top">Great idea, and I like the nearly duotone (without desaturation?) image. If only the background were less distracting, you''d have a winner.</td>', 'Great idea, and I like the nearly duotone (without desaturation?) image. If only the background were less distracting, you''d have a winner.', '2004-07-10 11:53:01.000000', NULL, 1),
(804785, 89268, 7485, '<td valign="top">Very nice use of shallow DOF, and good lighting. The dark corner on upper right is a bit distracting, and the frame really doesn''t work. My guess is that a subtle drop-shadow frame might have worked, if you really want a frame at all.</td>', 'Very nice use of shallow DOF, and good lighting. The dark corner on upper right is a bit distracting, and the frame really doesn''t work. My guess is that a subtle drop-shadow frame might have worked, if you really want a frame at all.', '2004-07-10 11:57:19.000000', NULL, 1),
(804786, 86860, 7485, '<td valign="top">I thought the idea was to *promote* the product?</td>', 'I thought the idea was to *promote* the product?', '2004-07-10 11:58:05.000000', NULL, 1),
(804790, 88858, 7485, '<td valign="top">Very clever! Maybe a bit of vignetting or a spotlight on the brush would''ve help bring the brush out even more.</td>', 'Very clever! Maybe a bit of vignetting or a spotlight on the brush would''ve help bring the brush out even more.', '2004-07-10 12:03:49.000000', NULL, 1),
(804792, 89173, 7485, '<td valign="top">Absolutely superb photo, probably a winner if it were in a challenge where it actually fit the theme - 7</td>', 'Absolutely superb photo, probably a winner if it were in a challenge where it actually fit the theme - 7', '2004-07-10 12:06:28.000000', NULL, 1),
(804798, 89284, 7485, '<td valign="top">Great idea! Too bad about that car in the upper left, it''s way too distracting.</td>', 'Great idea! Too bad about that car in the upper left, it''s way too distracting.', '2004-07-10 12:16:25.000000', NULL, 1),
(804803, 88890, 7485, '<td valign="top">Excellent! Best one I''ve seen so far. Getting the saturated glints just right while still having the darkest letters legible must have been quite a trick.</td>', 'Excellent! Best one I''ve seen so far. Getting the saturated glints just right while still having the darkest letters legible must have been quite a trick.', '2004-07-10 12:22:01.000000', NULL, 1),
(804808, 89263, 14593, '<td valign="top">nice photo.....I lived in Charlotte for 20 years.....Charlotte has really grown and changed....you captured the excitement of the place really nice....I like the lighting of the people down below, and the buildings up top.</td>', 'nice photo.....I lived in Charlotte for 20 years.....Charlotte has really grown and changed....you captured the excitement of the place really nice....I like the lighting of the people down below, and the buildings up top.', '2004-07-10 12:28:48.000000', NULL, 1),
