(806262, 89065, 23373, '<td valign="top">NIce comcept - might be better without the glare</td>', 'NIce comcept - might be better without the glare', '2004-07-11 19:29:25.000000', NULL, 1),
(806263, 86872, 23373, '<td valign="top">Subject needs to be in focus.</td>', 'Subject needs to be in focus.', '2004-07-11 19:30:41.000000', NULL, 1),
(806264, 88872, 23373, '<td valign="top">Like the translucency of the tangerine/orange slice. Wish it was a little sharper.</td>', 'Like the translucency of the tangerine/orange slice. Wish it was a little sharper.', '2004-07-11 19:32:44.000000', NULL, 1),
