(806269, 88675, 23373, '<td valign="top">Like the concept * background - very creative.</td>', 'Like the concept * background - very creative.', '2004-07-11 19:39:37.000000', NULL, 1),
(806289, 88925, 18349, '<td valign="top">Jeremy, if this isn''t yours, I must be blind...great shot!  (BTW...if it''s not Jeremy''s, I apologize...ignore me).  Beautiful colors and textures.  One of my favorites! :o)</td>', 'Jeremy, if this isn''t yours, I must be blind...great shot!  (BTW...if it''s not Jeremy''s, I apologize...ignore me).  Beautiful colors and textures.  One of my favorites! :o)', '2004-07-11 20:21:00.000000', NULL, 1),
(806290, 88816, 20214, '<td valign="top">Very porfessional looking! Good job.</td>', 'Very porfessional looking! Good job.', '2004-07-11 20:26:04.000000', NULL, 1),
(806293, 89251, 20214, '<td valign="top">A young Donald Trump! Good shot!</td>', 'A young Donald Trump! Good shot!', '2004-07-11 20:27:02.000000', NULL, 1),
(806294, 89169, 20214, '<td valign="top">Hope the Beta''s OK!!! Nice shot!</td>', 'Hope the Beta''s OK!!! Nice shot!', '2004-07-11 20:27:55.000000', NULL, 1),
