(806590, 88068, 6804, '<td valign="top">Very nice work!   the pastel colors and the clarity, just perfect on this!   10</td>', 'Very nice work!   the pastel colors and the clarity, just perfect on this!   10', '2004-07-12 00:31:38.000000', NULL, 1),
(806591, 88242, 6804, '<td valign="top">The color and the position on this is great. It could use a bit of sharpen/focus. I like the bright punch in this,  it shows the product well.</td>', 'The color and the position on this is great. It could use a bit of sharpen/focus. I like the bright punch in this,  it shows the product well.', '2004-07-12 00:33:46.000000', NULL, 1),
