(809028, 88242, 24072, '<td valign="top">I like the composition but I would have looked so much more refreshing with beads of water on the can. Good job!</td>', 'I like the composition but I would have looked so much more refreshing with beads of water on the can. Good job!', '2004-07-13 13:19:36.000000', NULL, 1),
(809031, 89284, 9690, '<td valign="top">You have a very distracting, brightly lit background.  Would have been better to keep that out of the shot and light the dog better.</td>', 'You have a very distracting, brightly lit background.  Would have been better to keep that out of the shot and light the dog better.', '2004-07-13 13:21:24.000000', NULL, 1),
