(809036, 89229, 9690, '<td valign="top">Great shot!  Very professional looking advertising shot.</td>', 'Great shot!  Very professional looking advertising shot.', '2004-07-13 13:24:16.000000', NULL, 1),
(809041, 87333, 9690, '<td valign="top">Like the mood here, but the light at the bottom is a little strong.  Also, the label on the beer looks like it got too wet and wrinkled.  An ad exec wouldnt want to see that.  I really like the way the light reflects off the glass an onto the bottle.</td>', 'Like the mood here, but the light at the bottom is a little strong.  Also, the label on the beer looks like it got too wet and wrinkled.  An ad exec wouldnt want to see that.  I really like the way the light reflects off the glass an onto the bottle.', '2004-07-13 13:26:29.000000', NULL, 1),
(809049, 88294, 15751, '<td valign="top">a nice ad shot, but the parking ligns take away somewhat from the studio look, if you will, and make it look more amature - therefore less advertisement-like.  still a good photo with excellent lighting, what a sexy machine!</td>', 'a nice ad shot, but the parking ligns take away somewhat from the studio look, if you will, and make it look more amature - therefore less advertisement-like.  still a good photo with excellent lighting, what a sexy machine!', '2004-07-13 13:32:34.000000', NULL, 1),
(809053, 89294, 24072, '<td valign="top">There''s gonna be some comments about the name of this product!</td>', 'There''s gonna be some comments about the name of this product!', '2004-07-13 13:36:06.000000', NULL, 1),
(809058, 88721, 19608, '<td valign="top">Great action shot - slight panning is really effective.</td>', 'Great action shot - slight panning is really effective.', '2004-07-13 13:39:14.000000', NULL, 1),
