(809107, 88657, 19608, '<td valign="top">Great idea - captivating model.  Lighting is really nice.  Too bad the aperture could not have been opened more to blur out the busy background.  The red lights just to the left of her hand are especailly distracting.</td>', 'Great idea - captivating model.  Lighting is really nice.  Too bad the aperture could not have been opened more to blur out the busy background.  The red lights just to the left of her hand are especailly distracting.', '2004-07-13 14:25:10.000000', NULL, 1),
(809108, 88293, 23618, '<td valign="top">Nice capture of all the little subtle colors and light in the glass and in the reflection of the bottle.</td>', 'Nice capture of all the little subtle colors and light in the glass and in the reflection of the bottle.', '2004-07-13 14:25:10.000000', NULL, 1),
(809109, 88821, 23618, '<td valign="top">Wow. Great visualization! :)</td>', 'Wow. Great visualization! :)', '2004-07-13 14:25:51.000000', NULL, 1),
