(809170, 89054, 19608, '<td valign="top">Nice colors and good use of the blue light.  It would be much better if it was not tilted.</td>', 'Nice colors and good use of the blue light.  It would be much better if it was not tilted.', '2004-07-13 15:15:29.000000', NULL, 1),
(809172, 89246, 19608, '<td valign="top">Excellent picnic theme - and perfect for the pickles.  Your use of the red-checkered tablecloth is a great touch.  The potato chip bags are pretty distracting.</td>', 'Excellent picnic theme - and perfect for the pickles.  Your use of the red-checkered tablecloth is a great touch.  The potato chip bags are pretty distracting.', '2004-07-13 15:19:43.000000', NULL, 1),
(809173, 88932, 19608, '<td valign="top">A very nice high-key rendition.  Very pleasing colors in a straight-forward composition.</td>', 'A very nice high-key rendition.  Very pleasing colors in a straight-forward composition.', '2004-07-13 15:21:15.000000', NULL, 1),
(809178, 88925, 19608, '<td valign="top">A great scene shot with just the right shutter speed for the water.  Water is a bit over exposed in spots and the large rock on the left side is really grabbing attention.  Itlooks like you picked a time of day with bright and contrasty light - but handled it pretty well.</td>', 'A great scene shot with just the right shutter speed for the water.  Water is a bit over exposed in spots and the large rock on the left side is really grabbing attention.  Itlooks like you picked a time of day with bright and contrasty light - but handled it pretty well.', '2004-07-13 15:24:36.000000', NULL, 1),
(809181, 89308, 19608, '<td valign="top">Superb!  Perfect use of DoF - just enough detail in the model to see the happy face  and the shampooed head.  Black background is really effective.  This is one of the [few] submissions I could actually picture in a magazine.</td>', 'Superb!  Perfect use of DoF - just enough detail in the model to see the happy face  and the shampooed head.  Black background is really effective.  This is one of the [few] submissions I could actually picture in a magazine.', '2004-07-13 15:26:59.000000', NULL, 1);
