(809800, 88885, 19944, '<td valign="top">Somehow, this doesn''t scream "Cod Liver Oil" to me.</td>', 'Somehow, this doesn''t scream "Cod Liver Oil" to me.', '2004-07-13 21:20:54.000000', NULL, 1),
(809803, 89340, 19944, '<td valign="top">Beautiful presentation.</td>', 'Beautiful presentation.', '2004-07-13 21:21:26.000000', NULL, 1),
