(818016, 88424, 17722, '<td valign="top">As a bartender who once worked at a Scotch bar, I certainly hope you used the 18 and not the 12 y.o. variety ;)<br/> <br/>Excellent shot!</td>', 'As a bartender who once worked at a Scotch bar, I certainly hope you used the 18 and not the 12 y.o. variety ;) Excellent shot!', '2004-07-20 10:08:26.000000', NULL, 0),
